107:         previousCurrentVisit.current &&
108:         currentVisit &&
109:         previousCurrentVisit.current.uuid === currentVisit.uuid &&
110:         !previousCurrentVisit.current.stopDatetime &&
111:         currentVisit.stopDatetime
112:       ) {
